 p=argparse.ArgumentParser(description=__doc__); p.add_argument("--benchmark",required=True,type=Path); p.add_argument("--variants",required=True,type=Path); p.add_argument("--rankings",required=True,type=Path); p.add_argument("--benchmark-audit",required=True,type=Path); p.add_argument("--variant-audit",required=True,type=Path); p.add_argument("--transformation-run",required=True,type=Path); p.add_argument("--review-template",required=True,type=Path); p.add_argument("--output-root",required=True,type=Path); a=p.parse_args(); report=evaluate(json.loads(a.benchmark.read_text()),json.loads(a.rankings.read_text()),benchmark_sha256=digest(a.benchmark),variants_sha256=digest(a.variants),rankings_sha256=digest(a.rankings)); a.output_root.mkdir(parents=True,exist_ok=True); evaluation=a.output_root/"evaluation.json"; html=a.output_root/"report.html"; evaluation.write_bytes(canonical_bytes(report)+b"\n"); render_html(report,html)
 artifacts={"benchmark":a.benchmark,"benchmark_audit":a.benchmark_audit,"human_review_template":a.review_template,"qwen_derived_sidecar":a.variants,"transformation_run":a.transformation_run,"variant_audit":a.variant_audit,"rankings":a.rankings,"evaluation":evaluation,"html_report":html}; commit=subprocess.run(["git","rev-parse","HEAD"],cwd=ROOT,text=True,capture_output=True,check=True).stdout.strip(); run=json.loads(a.transformation_run.read_text()); rankings=json.loads(a.rankings.read_text()); manifest={"contract_version":"f55c-exploratory-final-manifest-v1","evaluation_id":report["evaluation_id"],"code_commit_at_execution":commit,"execution":{"qwen":{"model_id":run["transformer"]["model_id"],"revision":run["transformer"]["revision"],"snapshot_manifest_sha256":run["transformer"]["artifact_manifest_sha256"],"generation":run["generation"]},"crosstext2loc":{"checkpoint_sha256":rankings["checkpoint_sha256"],"gallery_ids":rankings["gallery_ids"],"gallery_candidate_counts":{"madrid-25m":1115,"madrid-50m":253},"ranking_method":"exhaustive_cosine","top_k":10,"prefiltering":False,"reranking":False,"fine_tuning":False}},"artifacts":{name:{"logical_path":str(path.resolve().relative_to(ROOT)),"sha256":digest(path),"size_bytes":path.stat().st_size} for name,path in artifacts.items()},"ground_truth_kind":"synthetic_osm","real_ground_truth":False,"official_f54_metrics":False,"benchmark_human_reviewed":False,"variants_human_reviewed":False,"coordinates_used_for_retrieval":False,"provisional_execution":True}; (a.output_root/"manifest.json").write_bytes(canonical_bytes(manifest)+b"\n"); print(json.dumps({"evaluation_id":report["evaluation_id"],"rankings":report["coverage"]["observed_rankings"],"official_f54_metrics":False},sort_keys=True)); return 0
